// Helper function to count opening brackets
function count_opening_brackets(brackets: string, upTo: int): int
    requires 0 <= upTo <= brackets.Length
    ensures 0 <= count_opening_brackets(brackets, upTo) <= upTo
{
    var count := 0;
    var i := 0;
    while i < upTo
        invariant 0 <= i <= upTo
        invariant count == (count_opening_brackets(brackets, i))
    {
        if brackets[i] == '(' {
            count := count + 1;
        }
        i := i + 1;
    }
    return count;
}

